package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	input, _ := reader.ReadString('\n')
	input = strings.TrimSpace(input)

	count4 := 0
	count7 := 0

	if strings.Contains(input, "4") || strings.Contains(input, "7") {
		for _, r := range input {
			if r == '4' {
				count4++
			} else if r == '7' {
				count7++
			}
		}
		if count4 >= count7 {
			fmt.Println(4)
		} else {
			fmt.Println(7)
		}
	} else {
		fmt.Println(-1)
	}
}

